  next = drawFromDeck();
  nextAt = simTime + ROUND_MS;
  banners.push({ title: `第 ${round} 局`, sub: `中国地图 已拼成 ${chinaCount} 次`, dur: ROUND_MS + 400 });
  updateButtons();
