  grad.addColorStop(0, `rgba(255,255,244,${0.85 * a})`);
  grad.addColorStop(0.5, `rgba(255,250,222,${0.45 * a})`);
  grad.addColorStop(1, 'rgba(255,250,222,0)');
  g.fillStyle = grad;
